//! 命令分派。每个命令组一个文件，函数签名由骨架定死。

pub mod attempt;
pub mod gate;
pub mod self_cmd;
pub mod work;
pub mod workbook;

use sheltie_runtime::Home;

use crate::cli::{Cli, Group, SelfCmd, WorkCmd, WorkbookCmd};
use crate::output::{self, Outcome};

/// 一次调用共享的东西。
pub struct Ctx {
    pub home: Home,
    pub json: bool,
    pub request_id: Option<String>,
}

/// 解析管理根、分派到命令组、打印、返回退出码。
pub fn dispatch(cli: Cli) -> i32 {
    let raw = matches!(
        &cli.group,
        Group::Work(WorkCmd::Result { artifact, revision, .. })
            if artifact.is_some() || revision.is_some()
    );
    if raw && (cli.json || cli.request_id.is_some()) {
        return output::raw_param_error("原字节模式不支持 --json 或 --request-id");
    }
    if raw
        && !matches!(
            &cli.group,
            Group::Work(WorkCmd::Result { artifact: Some(_), revision: Some(revision), .. }) if *revision > 0
        )
    {
        return output::raw_param_error("--artifact 与正整数 --revision 必须同时出现");
    }
    let home = match Home::resolve(cli.home.as_deref()) {
        Ok(h) => h,
        Err(e) => {
            if raw {
                return output::raw_error(&e);
            }
            let out = crate::error_map::to_outcome(&e);
            output::print(&out, cli.json);
            return out.exit_code;
        }
    };
    // 只读操作与整个 self 组不支持 --request-id：给出即参数错误（协议 §1）。
    let read_only = matches!(
        cli.group,
        Group::SelfCmd(_)
            | Group::Workbook(
                WorkbookCmd::List | WorkbookCmd::Show { .. } | WorkbookCmd::Verify { .. }
            )
            | Group::Work(
                WorkCmd::List
                    | WorkCmd::Status { .. }
                    | WorkCmd::Result { .. }
                    | WorkCmd::Stats { .. }
            )
    );
    let cleanup_after_success = matches!(
        &cli.group,
        Group::Workbook(WorkbookCmd::Add { .. } | WorkbookCmd::Remove { .. })
            | Group::Work(WorkCmd::Start(_) | WorkCmd::Cancel { .. })
            | Group::Attempt(_)
            | Group::Gate(_)
    );
    let cleanup_tmp_after_success = match &cli.group {
        Group::SelfCmd(command) => !matches!(command, SelfCmd::Version),
        _ => cleanup_after_success,
    };
    if cli.request_id.is_some() && read_only {
        let out = crate::output::param_error(
            "--request-id 只用于 Work 与 Workbook 写操作；只读与 self 命令不支持".to_string(),
        );
        output::print(&out, cli.json);
        return out.exit_code;
    }
    let ctx = Ctx {
        home,
        json: cli.json,
        request_id: cli.request_id,
    };
    if let Group::Work(WorkCmd::Result {
        work,
        artifact: Some(key),
        revision: Some(revision),
    }) = &cli.group
    {
        return work::result_artifact(&ctx, work, key, *revision);
    }
    let outcome: Outcome = match cli.group {
        Group::SelfCmd(cmd) => self_cmd::run(&ctx, cmd),
        Group::Workbook(cmd) => workbook::run(&ctx, cmd),
        Group::Work(cmd) => work::run(&ctx, cmd),
        Group::Attempt(cmd) => attempt::run(&ctx, cmd),
        Group::Gate(cmd) => gate::run(&ctx, cmd),
    };
    output::print(&outcome, ctx.json);
    if outcome.exit_code == 0 && cleanup_tmp_after_success {
        if let Err(error) = ctx.home.cleanup_tmp() {
            eprintln!("warning: tmp维护未完成：{error}");
        }
    }
    if outcome.exit_code == 0 && cleanup_after_success {
        match sheltie_runtime::WorkbookRepo::new(ctx.home.clone()).cleanup_pending() {
            Ok(warnings) => {
                for warning in warnings {
                    eprintln!("warning: pending维护：{warning}");
                }
            }
            Err(error) => eprintln!("warning: pending维护未完成：{error}"),
        }
    }
    outcome.exit_code
}
//! `self install | update | rollback | uninstall | version`。除 `install` 建库外不打开 `store.db`。
//!
//! 不写任何宿主配置（`INV-3`）：`install` 的 PATH 只是提示文本。安装与更新的提示都要
//! 说清 当前 Store schema 与旧数据保留——rollback 只换回旧二进制，不降级 Store。

use serde_json::json;
use sheltie_runtime::selfmgmt;

use crate::cli::SelfCmd;
use crate::commands::Ctx;
use crate::output::{self, Outcome};

fn schema_note(ctx: &Ctx) -> String {
    format!(
        "Store schema 是 {}：旧数据保留在旧管理根，旧二进制拒绝当前格式的库。\
rollback 只换回旧二进制，不降级 Store；查旧记录要旧二进制配旧管理根。",
        selfmgmt::version_info(&ctx.home).schema_version
    )
}

/// `uninstall --purge` 在文本模式下没有 `--yes` 时读一行 stdin，必须是 `yes`；JSON 模式下必须给 `--yes`。
pub fn run(ctx: &Ctx, cmd: SelfCmd) -> Outcome {
    match cmd {
        SelfCmd::Install => install(ctx),
        SelfCmd::Update { version } => update(ctx, version.as_deref()),
        SelfCmd::Rollback => rollback(ctx),
        SelfCmd::Uninstall { purge, yes } => uninstall(ctx, purge, yes),
        SelfCmd::Version => version(ctx),
    }
}

/// `self install`。
fn install(ctx: &Ctx) -> Outcome {
    match selfmgmt::install(&ctx.home) {
        Ok(out) => {
            let data = json!({
                "installed_to": out.installed_to.as_str(),
                "already_installed": out.already_installed,
                "path_hint": out.path_hint,
            });
            let verb = if out.already_installed {
                "已装在"
            } else {
                "已装到"
            };
            let text = format!(
                "{verb} {}\n{}\n{}\n",
                out.installed_to,
                out.path_hint,
                schema_note(ctx)
            );
            output::ok(text, ctx.request_id.clone(), None, data, Vec::new())
        }
        Err(e) => crate::error_map::to_outcome(&e),
    }
}

/// `self update`。
fn update(ctx: &Ctx, version: Option<&str>) -> Outcome {
    let source = selfmgmt::ReleaseSource::from_env();
    match selfmgmt::update(&ctx.home, &source, version) {
        Ok(out) => {
            let data = json!({
                "from": out.from,
                "to": out.to,
                "up_to_date": out.up_to_date,
            });
            let head = if out.up_to_date {
                format!("已是最新（{}）\n", out.to)
            } else {
                format!("已从 {} 升到 {}\n", out.from, out.to)
            };
            let text = format!("{head}{}\n", schema_note(ctx));
            output::ok(text, ctx.request_id.clone(), None, data, Vec::new())
        }
        Err(e) => crate::error_map::to_outcome(&e),
    }
}

/// `self rollback`。
fn rollback(ctx: &Ctx) -> Outcome {
    match selfmgmt::rollback(&ctx.home) {
        Ok(()) => output::ok(
            "已换回上一版本\n".to_string(),
            ctx.request_id.clone(),
            None,
            json!({ "rolled_back": true }),
            Vec::new(),
        ),
        Err(e) => crate::error_map::to_outcome(&e),
    }
}

/// `self uninstall [--purge]`。
fn uninstall(ctx: &Ctx, purge: bool, yes: bool) -> Outcome {
    // 只有 purge 要确认；文本模式读一行 stdin，JSON 模式必须给 --yes（协议 §3 self uninstall）。
    let confirmed = if !purge || yes {
        true
    } else if ctx.json {
        false
    } else {
        println!(
            "将清理管理根中的 Workbook、Work、pending、临时文件、binary 与数据库；保留根目录和锁文件：{}",
            ctx.home.root().as_str()
        );
        let mut line = String::new();
        match std::io::stdin().read_line(&mut line) {
            Ok(_) => line.trim() == "yes",
            Err(_) => false,
        }
    };
    match selfmgmt::uninstall(&ctx.home, purge, confirmed) {
        Ok(kept) => {
            if purge {
                return output::ok(
                    format!(
                        "已清理管理数据与 binary。保留：\n  {}\n  {}\n",
                        ctx.home.root(),
                        ctx.home.lock_path()
                    ),
                    ctx.request_id.clone(),
                    None,
                    json!({ "kept": kept.iter().map(|path| path.as_str()).collect::<Vec<_>>() }),
                    Vec::new(),
                );
            }
            let mut text = String::from("已删 bin/。保留：\n");
            let mut paths = Vec::with_capacity(kept.len());
            for p in &kept {
                text.push_str(&format!("  {}\n", p.as_str()));
                paths.push(p.as_str());
            }
            output::ok(
                text,
                ctx.request_id.clone(),
                None,
                json!({ "kept": paths }),
                Vec::new(),
            )
        }
        Err(e) => crate::error_map::to_outcome(&e),
    }
}

/// `self version`。只读，不建管理根。
fn version(ctx: &Ctx) -> Outcome {
    let info = selfmgmt::version_info(&ctx.home);
    let data = json!({
        "version": info.version,
        "platform": info.platform,
        "home": info.home.as_str(),
        "schema_version": info.schema_version,
    });
    let text = format!(
        "sheltie {}\nplatform: {}\nhome: {}\nSCHEMA_VERSION: {}\n",
        info.version,
        info.platform,
        info.home.as_str(),
        info.schema_version
    );
    output::ok(text, None, None, data, Vec::new())
}

